        dr = 1 if sum(r for r,c in ps)/len(ps) > cr else -1
        dc = 1 if sum(c for r,c in ps)/len(ps) > cc else -1
        same_col = len({c for r,c in ps}) < len(ps)
        same_row = len({r for r,c in ps}) < len(ps)
